// ---- Mars Life Line style header (generated by scripts/kiln-style-sync.mjs from src/style/tokens.json, style v2) ----
// Paste at the top of every .kiln.js source. Do not edit colours here; edit tokens.json and re-run npm run style:sync.
const PALETTE = {
  'space-deep': 0x20283D,
  'shadow-plum': 0x765768,
  'regolith-mid': 0xB95C40,
  'regolith-light': 0xE6A26A,
  'structure-white': 0xF2E5D2,
  'structure-gray': 0x686976,
  'trim-dark': 0x303240,
  'accent-orange': 0xFF8A24,
  'accent-cyan': 0x54E5F5,
  'accent-blue': 0x35CFFF,
  'glass-tint': 0xEBD9C5,
  'cell-blue': 0x2F58B8
};

const BUDGETS = {"small-prop":1500,"medium-prop":6000,"vehicle":9000,"building":12000,"character":8000,"rock":400};
const SEGMENTS = {"small":8,"default":12,"large":16};

// Bevel radius for roundedBoxGeo: ratio of the smallest dimension (style range 0.06-0.12).
function bevel(w, h, d, ratio = 0.09) {
  return Math.min(w, h, d) * ratio;
}

// One shared material per role. Variants (e.g. structure-gray) take an explicit colour token.
function styleMaterials() {
  const m = {"matte-environment":{"description":"Terrain, rocks, craters, mountains. Fully matte, no reflections.","colors":["regolith-mid","regolith-light","shadow-plum"],"roughness":0.95,"metalness":0},"smooth-structure":{"description":"Buildings, modules, vehicles, suits, crates. Clean satin finish, never mirror-like.","colors":["structure-white","structure-gray"],"roughness":0.55,"metalness":0.05},"accent-paint":{"description":"Non-glowing orange colour blocking: side panels, crate faces, dome base band, suit pads, wheel hubs.","colors":["accent-orange"],"roughness":0.6,"metalness":0},"dark-trim":{"description":"Tyres, recesses, joints, vents.","colors":["trim-dark"],"roughness":0.85,"metalness":0},"emissive-warm":{"description":"Door frames, window strips, headlights. Selected surfaces only.","colors":["accent-orange"],"emissive":"accent-orange","emissiveIntensity":1.6,"roughness":0.5,"metalness":0},"emissive-cool":{"description":"Beacons, indicators, screens. Smaller and rarer than warm lights.","colors":["accent-cyan","accent-blue"],"emissive":"accent-cyan","emissiveIntensity":1.4,"roughness":0.5,"metalness":0},"glass":{"description":"Greenhouse domes, module windows. Light tint, soft highlight, see-through.","colors":["glass-tint"],"roughness":0.15,"metalness":0,"opacity":0.35},"visor":{"description":"Helmet visors and vehicle windshields. Opaque near-black, glossy, shows a soft highlight.","colors":["space-deep"],"roughness":0.12,"metalness":0.1},"solar-cell":{"description":"Solar panel cell faces. Deep blue, semi-gloss, framed by structure-white grid bars.","colors":["cell-blue"],"roughness":0.35,"metalness":0.1}};
  const make = (role, colorToken) => {
    const spec = m[role];
    const color = PALETTE[colorToken ?? spec.colors[0]];
    const name = colorToken && colorToken !== spec.colors[0] ? role + ':' + colorToken : role;
    if (role === 'glass') return glassMaterial(color, { opacity: spec.opacity, roughness: spec.roughness, metalness: spec.metalness, name });
    const opts = { roughness: spec.roughness, metalness: spec.metalness, name };
    if (spec.emissive) Object.assign(opts, { emissive: PALETTE[spec.emissive], emissiveIntensity: spec.emissiveIntensity });
    return gameMaterial(color, opts);
  };
  return {
    rock: make('matte-environment'),
    rockLight: make('matte-environment', 'regolith-light'),
    rockShadow: make('matte-environment', 'shadow-plum'),
    panel: make('smooth-structure'),
    panelGray: make('smooth-structure', 'structure-gray'),
    accent: make('accent-paint'),
    trim: make('dark-trim'),
    glowWarm: make('emissive-warm'),
    glowCool: make('emissive-cool'),
    glowBlue: make('emissive-cool', 'accent-blue'),
    glass: make('glass'),
    visor: make('visor'),
    solarCell: make('solar-cell'),
  };
}
// ---- end style header ----

const meta = {
  name: 'landing-ship-cabin',
  role: 'building',
  reference: 'models and assets images/phase-4/landing-ship-cabin.png'
};

async function build() {
  const root = createRoot('landing-ship-cabin');
  const m = styleMaterials();
  const green = gameMaterial(0x79CFAA, { roughness: .55, emissive: 0x286747, emissiveIntensity: .35, name: 'status-green' });
  const screen = gameMaterial(0x101D2C, { roughness: .55, emissive: 0x173747, emissiveIntensity: .35, name: 'instrument-glass' });
  const white = gameMaterial(PALETTE['structure-white'], { roughness: .65, name: 'panel-lettering' });
  const box = (name, size, pos, mat = m.panelGray, parent = root, rotation) => createPart(name, boxGeo(...size), mat, { position: pos, parent, rotation });
  const round = async (name, size, pos, mat = m.panelGray, parent = root, rotation) => createPart(name, await roundedBoxGeo(...size, Math.min(...size) * .12, { style: 'chamfer' }), mat, { position: pos, parent, rotation });
  const cyl = (name, radius, height, pos, mat = m.trim, parent = root, rotation) => createPart(name, cylinderGeo(radius, radius, height, 12), mat, { position: pos, parent, rotation });
  // Full consumer cabin: floor top .92, clear headroom 2.66m. +Z is the viewport.
  box('CabinFloor', [4.9,.18,4.8], [0,.83,-.75]);
  box('AftBulkhead', [4.9,2.8,.16], [0,2.24,-3.15], m.panel);
  box('PortBulkhead', [.16,2.8,4.8], [-2.45,2.24,-.75], m.panel);
  box('StarboardBulkhead', [.16,2.8,4.8], [2.45,2.24,-.75], m.panel);
  box('Ceiling', [4.9,.16,4.8], [0,3.66,-.75], m.panelGray);
  // The forward wall is an opening, not an opaque display window.
  box('WindowSill', [4.9,.75,.18], [0,1.295,1.65], m.panel);
  box('WindowHeader', [4.9,.43,.18], [0,3.445,1.65], m.panel);
  for (const x of [-2.23,2.23]) box('ViewportPillar_'+x, [.44,1.56,.22], [x,2.46,1.62]);
  for (const x of [-.98,.98]) box('ViewportMullion_'+x, [.045,1.54,.13], [x,2.46,1.68], m.trim);
  for (const z of [-2.65,-1.4,-.15,1.2]) {
    box('CeilingBeam_'+z, [4.7,.14,.12], [0,3.51,z]);
    for (const x of [-2.3,2.3]) box('WallRib_'+x+'_'+z, [.16,2.55,.12], [x,2.2,z]);
  }
  // Inset service panels, floor plates, aisle markings and handrails.
  for (let i=0;i<7;i++) {
    const z=-2.82+i*.62;
    box('DeckPlate_'+i, [1.26,.018,.57], [0,.929,z], m.trim);
    for (const x of [-.72,.72]) box('AisleStripe_'+x+'_'+i, [.035,.021,.4], [x,.932,z], m.accent);
    for (const x of [-1.65,1.65]) box('OutboardDeck_'+x+'_'+i,[1.35,.016,.57],[x,.927,z]);
  }
  for (const x of [-2.34,2.34]) {
    for (let i=0;i<3;i++) {
      const z=-2.35+i*1.25;
      box('WallInset_'+x+'_'+i,[.025,1.2,1.06],[x,2.3,z],m.trim);
      box('ServiceCover_'+x+'_'+i,[.035,1.07,.92],[x*.992,2.3,z],m.panel);
      for (let k=0;k<4;k++) box('ServiceVent_'+x+'_'+i+'_'+k,[.045,.027,.39],[x*.979,2.02+k*.065,z]);
    }
    cyl('GrabRail_'+x,.028,2.9,[x*.96,1.83,-.85],m.accent,root,[90,0,0]);
    for (const z of [-2.25,.55]) box('RailBracket_'+x+'_'+z,[.14,.08,.08],[x*.975,1.83,z]);
    box('UpperConduit_'+x,[.08,.08,4.35],[x*.95,3.28,-.75],m.trim);
    for (const z of [-2.8,-1.7,-.6,.5]) box('ConduitClamp_'+x+'_'+z,[.13,.13,.06],[x*.95,3.28,z]);
  }
  // Broad instrument desk, three display recesses, tactile lower key rows.
  await round('ConsolePlinth',[3.9,.64,.73],[0,1.24,1.1],m.accent);
  box('ConsoleKickRecess',[3.65,.18,.04],[0,1.05,.714],m.trim);
  const desk = createPivot('ConsoleGroup',[0,1.8,1.08],root);
  desk.rotation.x=Math.PI/4;
  await round('ConsoleFace',[3.94,.82,.12],[0,0,0],m.panel,desk);
  box('ConsoleFaceInset',[3.75,.67,.025],[0,0,-.073],m.trim,desk);
  for (let i=0;i<3;i++) {
    const x=(i-1)*.73;
    await round('DisplayBezel_'+i,[.66,.39,.045],[x,.1,-.1],m.panelGray,desk);
    box('DisplaySurface_'+i,[.57,.30,.014],[x,.1,-.131],screen,desk);
    for (let k=0;k<4;k++) {
      box('DisplaySoftKey_'+i+'_'+k,[.075,.038,.026],[x-.19+k*.127,-.14,-.105],m.panelGray,desk);
    }
  }
  for (let row=0;row<2;row++) for (let col=0;col<18;col++) {
    const x=-1.1+col*.13;
    await round('Key_'+row+'_'+col,[.085,.058,.033],[x,-.23-row*.083,-.104],col%6===0?m.accent:m.panelGray,desk);
  }
  // Two rotary encoder banks, status lamps, guarded arm and abort switches.
  for (const side of [-1,1]) {
    const x=side*1.53;
    for (let k=0;k<3;k++) {
      const y=.23-k*.19;
      cyl('EncoderBase_'+side+'_'+k,.079,.018,[x,y,-.105],m.panelGray,desk,[90,0,0]);
      const dial=createPivot('encoder_'+side+'_'+k,[x,y,-.13],desk);
      cyl('EncoderGrip_'+side+'_'+k,.052,.055,[0,0,0],m.trim,dial,[90,0,0]);
      box('EncoderPointer_'+side+'_'+k,[.012,.037,.008],[0,.015,-.033],white,dial);
      box('EncoderScale_'+side+'_'+k,[.1,.008,.012],[x,y+.09,-.105],white,desk);
    }
    for(let k=0;k<5;k++) cyl('StatusLamp_'+side+'_'+k,.018,.018,[side*1.85,.28-k*.105,-.095],k===3?m.glowWarm:green,desk,[90,0,0]);
  }
  const arm = createPivot('button_arm', [1.23,1.54,.71],root);
  cyl('ArmBezel',.085,.032,[0,0,0],m.trim,arm,[90,0,0]);
  cyl('ArmCap',.062,.045,[0,0,-.025],m.accent,arm,[90,0,0]);
  for(const x of [-.09,.09]) box('ArmGuard_'+x,[.025,.17,.13],[x,.015,-.02],m.accent,arm);
  // Twin throttle levers beside the flight panel. Proper pivots for live motion.
  for(let i=0;i<2;i++) {
    const x=-1.56+i*.19;
    box('ThrottleSlot_'+i,[.065,.36,.03],[x,1.65,.70],m.trim);
    const lever=createPivot('throttle_'+i,[x,1.52,.66],root);
    cyl('ThrottleShaft_'+i,.016,.28,[0,.12,0],m.panelGray,lever);
    await round('ThrottleGrip_'+i,[.13,.075,.08],[0,.28,0],i?m.accent:m.trim,lever);
  }
  // Two flight seats leave a 1.3m center aisle and room to walk behind.
  for(const x of [-1.22,1.22]) {
    const seat=createPivot('seat_'+(x<0?'port':'starboard'),[x,.92,-.55],root);
    cyl('SeatBase_'+x,.26,.16,[0,.08,0],m.panelGray,seat);
    box('SeatRails_'+x,[.62,.08,.78],[0,.18,0],m.trim,seat);
    box('SeatSuspension_'+x,[.48,.13,.50],[0,.25,0],m.panelGray,seat);
    await round('SeatPan_'+x,[.72,.18,.73],[0,.36,0],m.panelGray,seat);
    await round('SeatCushion_'+x,[.61,.10,.60],[0,.48,0],m.accent,seat);
    await round('SeatBack_'+x,[.72,.93,.17],[0,.91,-.37],m.panelGray,seat,[-8,0,0]);
    await round('SeatBackPad_'+x,[.59,.78,.10],[0,.91,-.265],m.accent,seat,[-8,0,0]);
    await round('Headrest_'+x,[.42,.23,.17],[0,1.48,-.45],m.trim,seat);
    for(const side of [-1,1]) {
      box('Harness_'+x+'_'+side,[.065,.71,.025],[side*.18,.92,-.20],m.trim,seat,[-8,0,0]);
      box('Armrest_'+x+'_'+side,[.09,.09,.55],[side*.40,.65,0],m.trim,seat);
      box('ArmSupport_'+x+'_'+side,[.055,.30,.06],[side*.40,.47,.19],m.panelGray,seat);
    }
    box('HarnessBuckle_'+x,[.15,.10,.05],[0,.55,-.15],m.panelGray,seat);
  }
  // Overhead electrics with breakers and toggle rows.
  for(const x of [-1.1,1.1]) box('OverheadMount_'+x,[.12,.35,.14],[x,3.46,.38],m.panelGray);
  const overhead=createPivot('Overhead',[0,3.22,.38],root); overhead.rotation.x=-Math.PI/5;
  await round('OverheadHousing',[2.7,.42,.18],[0,0,0],m.panelGray,overhead);
  box('OverheadInset',[2.5,.30,.024],[0,0,-.104],m.trim,overhead);
  for(let i=0;i<16;i++) {
    const x=-1.15+i*.153;
    cyl('BreakerBase_'+i,.033,.018,[x,0,-.13],m.panelGray,overhead,[90,0,0]);
    box('BreakerToggle_'+i,[.021,.075,.025],[x,.025,-.15],i%4===0?m.accent:white,overhead,[20,0,0]);
    cyl('BreakerLED_'+i,.012,.012,[x,.105,-.13],i%5===0?m.glowWarm:green,overhead,[90,0,0]);
  }
  // Aft equipment lockers, strapped oxygen tanks and hatch wheel.
  for(const x of [-1.63,1.63]) {
    await round('AftLocker_'+x,[.92,1.73,.48],[x,1.8,-2.8],m.panelGray);
    box('LockerDoor_'+x,[.78,1.56,.035],[x,1.8,-2.54],m.panel);
    box('LockerLatch_'+x,[.065,.23,.055],[x+.26,1.88,-2.50],m.trim);
    for(let i=0;i<5;i++) box('LockerVent_'+x+'_'+i,[.48,.025,.02],[x,1.22+i*.07,-2.51],m.trim);
    box('LockerStripe_'+x,[.78,.085,.025],[x,2.28,-2.51],m.accent);
  }
  const hatch=createPivot('hatch',[0,1.96,-3.03],root);
  await round('HatchFrame',[1.45,2.08,.13],[0,0,0],m.panelGray,hatch);
  await round('HatchOrangeGasket',[1.24,1.88,.14],[0,0,.035],m.accent,hatch);
  await round('HatchDoorPlate',[1.1,1.75,.15],[0,0,.075],m.panel,hatch);
  createPart('HatchWheel',torusGeo(.21,.028,6,16),m.trim,{position:[.2,0,.20],parent:hatch});
  for(let i=0;i<3;i++) box('HatchWheelSpoke_'+i,[.40,.028,.035],[.2,0,.20],m.trim,hatch,[0,0,i*60]);
  cyl('HatchWheelHub',.05,.07,[.2,0,.21],m.accent,hatch,[90,0,0]);
  for(const x of [-2.03,2.03]) {
    const o2=createPivot('o2_'+x,[x,1.68,-1.88],root);
    cyl('OxygenTank_'+x,.15,1.0,[0,0,0],m.panel,o2);
    cyl('OxygenShoulder_'+x,.10,.12,[0,.55,0],m.panelGray,o2);
    cyl('OxygenValve_'+x,.038,.10,[0,.66,0],m.accent,o2);
    for(const y of [-.30,.30]) cyl('TankStrap_'+x+'_'+y,.16,.075,[0,y,0],m.trim,o2);
    box('TankMount_'+x,[.34,1.1,.08],[0,0,-.15],m.panelGray,o2);
  }
  // Warm fixtures and caged floor lights; no emissive wash across the whole room.
  for(const x of [-1.65,1.65]) for(const z of [-2.2,-.6,.9]) {
    box('LightHousing_'+x+'_'+z,[.42,.06,.56],[x,3.55,z],m.trim);
    box('LightDiffuser_'+x+'_'+z,[.32,.025,.44],[x,3.506,z],m.glowWarm);
    for(let i=0;i<3;i++) box('LightGuard_'+x+'_'+z+'_'+i,[.35,.025,.018],[x,3.485,z-.15+i*.15],m.panelGray);
  }
  for(const x of [-2.36,2.36]) for(const z of [-2.4,-1.1,.2]) box('FootLight_'+x+'_'+z,[.035,.045,.26],[x,1.12,z],m.glowWarm);
  // Fasteners on the major panel seams, large enough to read at walking distance.
  for(const x of [-1.90,1.90]) for(const y of [-.34,.34]) cyl('ConsoleFastener_'+x+'_'+y,.019,.012,[x,y,-.075],m.panelGray,desk,[90,0,0]);
  defineBudget({ triangles: 18000 },root);
  return root;
}
